
const IMG={"shift": "data:image/jpeg;base64,", "alu": "data:image/jpeg;base64,", "virkon": "data:image/jpeg;base64,", "farm": "data:image/jpeg;base64,", "bio": "data:image/jpeg;base64,", "gpc": "data:image/jpeg;base64,", "biocid": "data:image/jpeg;base64,", "dry": "data:image/jpeg;base64,", "water": "data:image/jpeg;base64,", "ift": "data:image/jpeg;base64,"};const PACKS=[["Virkon S", 50, "kg", 45742, "virkon"], ["Virkon S", 10, "kg", 12245, "virkon"], ["Virkon Fog Enhancer", 20, "L", 15939, ""], ["Farmfluid S", 25, "L", 15484, "farm"], ["Farmfluid S", 5, "L", 3694, "farm"], ["BioSentry 904", 18.92705892, "L", 22770, "bio"], ["BioSentry 904", 3.785411784, "L", 5060, "bio"], ["GPC-8", 5, "L", 4048, "gpc"], ["Shift", 5, "L", 2429, "shift"], ["Biocid 30", 5, "L", 5718, "biocid"], ["Peraclean 15", 30, "kg", 15939, ""], ["Oxteril 350 Combi", 30, "kg", 11587, ""], ["AluSafe Tray Wash", 20, "L", 5465, "alu"]];
