function nav(t){for(const x of ['planner','catalog','report']){$(x).classList.toggle('hide',x!==t);$('nav'+x[0].toUpperCase()+x.slice(1)).classList.toggle('active',x===t)}if(t==='report')renderReport();window.scrollTo({top:0,behavior:'smooth'})}
const STAGES=[['insect','رش المبيد الحشري'],['dry','النظافة الجافة'],['water','غسلة المياه البيضاء'],['prep','ممهدات التطهير'],['drying','الجفاف'],['general','التطهير العام'],['pads','تطهير خلايا التبريد'],['lines','تطهير خطوط النبل والخزانات'],['cocci','تطهير الكوكسيديا (عند الحاجة)'],['fog','التبخير الحراري']];
function start(){if(!num('len')||!num('wid')||!num('hei')||!num('houses')){alert('أدخل أبعاد العنبر وعدد العنابر بشكل صحيح');return}if($('housing').value==='battery'&&(!num('batL')||!num('batW')||!num('batH')||!num('batRows'))){alert('أدخل أبعاد البطاريات وعدد صفوفها');return}$('setup').classList.add('hide');$('wizard').classList.remove('hide');step=0;renderStep()}
function fieldSelect(id,options,chosen){return `<select id="${id}">${options.map(([v,label])=>`<option value="${v}" ${String(v)===String(chosen)?'selected':''}>${label}</option>`).join('')}</select>`}
function area(){return num('len')*num('wid')*3*num('houses')};function floorArea(){return num('len')*num('wid')*num('houses')};function houseVolume(){return num('len')*num('wid')*num('hei')*num('houses')}
function stageForm(key){let cfg=stageSettings[key]||{};let opts=key==='prep'?[['Shift','Shift'],['AluSafe Tray Wash','AluSafe Tray Wash']]:[['Virkon S','Virkon S'],['Farmfluid S','Farmfluid S'],['BioSentry 904','BioSentry 904'],['GPC-8','GPC-8'],['Biocid 30','Biocid 30'],['Peraclean 15','Peraclean 15'],['Oxteril 350 Combi','Oxteril 350 Combi']];let chosen=cfg.product||opts[0][0];let method=cfg.method||'spray';return `<p class="muted">اختر المنتج وطريقة التطبيق، ثم راجع الجرعة والنشرة الفنية قبل اعتماد الحساب.</p><div class="grid2"><div><label>المنتج</label>${fieldSelect('product',opts,chosen)}</div><div><label>طريقة التطبيق</label><select id="method"><option value="spray" ${method==='spray'?'selected':''}>رش</option><option value="foam" ${method==='foam'?'selected':''}>فوم (Shift فقط)</option></select></div><div><label>معدل تغطية الرش (مل/م²)</label><select id="coverage"><option value="250">250</option><option value="275">275</option><option value="300">300</option></select></div><div><label>جرعة المنتج (مل/لتر أو جرام/لتر)</label><input id="dose" type="number" step="0.1" min="0" placeholder="أدخل الجرعة المعتمدة"></div></div><div id="calcPreview" class="good" style="margin-top:12px"></div><div class="actions"><button onclick="addCurrent()">إضافة هذا التطبيق للتقرير</button></div><p class="muted">لمنتجات التطهير العام غير Shift وAluSafe: أدخل الجرعة المعتمدة من الملصق. لن نفترض جرعة غير موثقة.</p>`}
const V13_STAGE_VISUAL={"dry":"data:image/jpeg;base64,","water":"data:image/jpeg;base64,","prep":"data:image/jpeg;base64,","drying":"data:image/jpeg;base64,","general":"data:image/jpeg;base64,","pads":"data:image/jpeg;base64,","lines":"data:image/jpeg;base64,","fog":"data:image/jpeg;base64,"};
function renderStep(){const [key,title]=STAGES[step];$('steps').innerHTML=STAGES.map((s,i)=>`<span class="${i===step?'on':''}">${i+1}. ${s[1]}</span>`).join('');let html=`<span class="pill">الخطوة ${step+1} من ${STAGES.length}</span><h2 style="margin-top:13px">${title}</h2>${V13_STAGE_VISUAL[key]?`<img class="v13-stage-photo" src="${V13_STAGE_VISUAL[key]}" alt="صورة توضيحية: ${title}" loading="lazy">`:``}`;
if(key==='insect')html+=`<p>رش مبيد حشري مناسب بعد خروج الطيور وقبل النظافة الجافة. في التربية الأرضية تُجمع السبلة في منتصف العنبر وتُرش قبل النقل للحد من انتشار الحشرات.</p><div class="stat">مساحة الرش التقديرية (أرضية + 0.5م أسفل الحوائط): <b>${fmt((num('len')*num('wid')+(2*(num('len')+num('wid'))*.5))*num('houses'))} م²</b>كمية المحلول المخفف: <b>${fmt((num('len')*num('wid')+(num('len')+num('wid'))*1)*num('houses')/10)} لتر</b></div><p class="muted">محلول مخفف وليس مبيدًا مركزًا. لا يوجد مبيد حشري من منتجات إينوفال هنا، لذلك لا تُحسب تكلفة منتج.</p>`;
if(key==='dry')html+=`<p>إزالة المواد العضوية والمخلفات دون استخدام المياه أو المطهرات.</p><div class="drylist"><div><b>1. الكنس</b>كنس الأرضيات والممرات</div><div><b>2. الكحت</b>إزالة الرواسب الملتصقة بالأسطح</div><div><b>3. الشقرفة</b>تجميع ورفع السبلة والمخلفات</div><div><b>4. النفخ (Air Blower)</b>نفخ الأتربة من المناطق صعبة الوصول مع التحكم في انتشار الغبار</div><div><b>5. النظافة الخارجية</b>الطرق والممرات ومخازن الأعلاف وسكن العاملين ومحيط المزرعة</div></div>${IMG.dry?`<img class="pic" style="height:280px;margin-top:12px" src="${IMG.dry}" alt="النفخ باستخدام منفاخ هواء">`:''}<p class="muted">ارتدِ معدات الوقاية وتجنب نشر الغبار بين العنابر. لا توجد كمية مياه أو تكلفة منتج.</p>`;
if(key==='water')html+=`${IMG.water?`<img class="pic" style="height:270px" src="${IMG.water}" alt="غسيل العنبر بالمياه بدون صابون">`:''}<p>استخدام مياه مفتوحة بضغط متوسط لغسيل وترطيب العنبر وإزالة بقايا المواد العضوية من الأسطح والأدوات والمعدات، تمهيدًا لممهدات التطهير للتعامل مع الرواسب الصلبة الملتصقة.</p><div class="good">لا يتم حساب كمية المياه أو اختيار منتج أو حساب تكلفة لهذه المرحلة.</div>`;
if(key==='drying')html+=`<p>ترك الأسطح والمعدات حتى تجف بعد شطف ممهد التطهير وقبل تطبيق المطهر، وفق التعليمات الفنية.</p><div class="good">مرحلة إرشادية بدون كميات أو تكاليف.</div>`;
if(key==='prep'||key==='general')html+=stageForm(key);
if(key==='pads')html+=`<p>تطهير خلايا التبريد وفق تعليمات المنتج وتوافقه مع خامات الخلايا. تُحدد كمية المحلول حسب حجم النظام الفعلي وليس مساحة أرضية العنبر.</p><label>حجم المحلول المخفف المطلوب (لتر)</label><input type="number" id="specialLiters" min="0" placeholder="حجم النظام الفعلي"><div class="actions"><button onclick="addSpecial('pads')">إضافة تطبيق بخطوة مخصصة</button></div><p class="muted">أدخل الحجم والمنتج والجرعة من النشرة المعتمدة؛ لا تُفترض جرعة تلقائيًا.</p>`;
if(key==='lines')html+=`<p>تطهير خطوط النبل وخزانات المياه بناءً على الحجم الحقيقي للخزانات والخطوط، مع الالتزام بالجرعات واشتراطات الشطف المعتمدة لمياه الشرب.</p><label>حجم الخطوط والخزانات (لتر)</label><input type="number" id="specialLiters" min="0" placeholder="الحجم الفعلي"><div class="actions"><button onclick="addSpecial('lines')">إضافة تطبيق بخطوة مخصصة</button></div>`;
if(key==='cocci')html+=`<p>هذه الخطوة اختيارية عند وجود تاريخ إصابة بالكوكسيديا. لا يُعرض منتج على أنه فعال ضد الأكياس البيضية إلا إذا كانت الفاعلية مثبتة على ملصقه المعتمد.</p><div class="notice">لا توجد توصية أو جرعة تلقائية لهذه الخطوة حاليًا؛ تُسجل كتوجيه يحتاج مراجعة فنية.</div>`;
if(key==='fog')html+=`<p>التبخير الحراري: يعتمد حجم المياه على حجم العنبر ونظام التربية. المعادلات التالية قواعد تشغيل مدخلة وتحتاج مطابقة النشرة الفنية قبل الاستخدام.</p><div class="grid2"><div class="stat">حجم العنبر الكلي<b>${fmt(houseVolume())} م³</b></div><div class="stat">مياه التبخير<b>${fmt(houseVolume()/($('housing').value==='battery'?1250:1850))} لتر</b></div><div class="stat">GPC-8 المركز (5 مل/لتر)<b>${fmt(houseVolume()/($('housing').value==='battery'?1250:1850)*.005)} لتر</b></div><div class="stat">Fog Enhancer (1 لتر لكل 5 لتر GPC-8)<b>${fmt(houseVolume()/($('housing').value==='battery'?1250:1850)*.001)} لتر</b></div></div><div class="notice" style="margin-top:12px">معدل Fog Enhancer المذكور يتعارض مع معدل سابق (60–80 مل/لتر ماء). لا يُفعّل احتساب العبوات أو التكلفة لهذه الخطوة قبل تأكيد الجرعة الفنية الصحيحة.</div>`;
html+=`<div class="actions"><button class="alt" onclick="go(-1)">${step===0?'بيانات المزرعة':'السابق'}</button><button class="gold" onclick="go(1)">${step===STAGES.length-1?'عرض التقرير':'التالي'}</button></div>`;$('stepContent').innerHTML=html;if(key==='prep'||key==='general'){let p=$('product');p.onchange=refreshProduct;$('method').onchange=refreshProduct;$('coverage').onchange=preview;$('dose').oninput=preview;refreshProduct()}}
function refreshProduct(){let p=$('product').value,m=$('method');if(p==='Shift'){m.disabled=false;$('dose').value=m.value==='foam'?8:4;$('coverage').disabled=m.value==='foam'}else if(p==='AluSafe Tray Wash'){m.value='spray';m.disabled=true;$('dose').value=5;$('coverage').disabled=false}else{m.value='spray';m.disabled=true;$('dose').value='';$('coverage').disabled=false}preview()}
function preview(){let m=$('method').value,cov=m==='foam'?500:Number($('coverage').value),sol=area()*cov/1000,dose=num('dose'),qty=sol*dose/1000;$('calcPreview').textContent=`مساحة الرش التقديرية: ${fmt(area())} م² | المحلول المخفف: ${fmt(sol)} لتر | المنتج المركز: ${fmt(qty)} ${$('product').value==='Virkon S'?'كجم':'لتر'} ${dose?'':'(أدخل الجرعة)'}`}
function addCurrent(){let key=STAGES[step][0],p=$('product').value,m=$('method').value,dose=num('dose');if(!dose){alert('أدخل جرعة المنتج من النشرة الفنية أولًا');return}let cov=m==='foam'?500:Number($('coverage').value),sol=area()*cov/1000,qty=sol*dose/1000;records.push({stage:STAGES[step][1]+(m==='foam'?' — فوم':' — رش'),product:p,solution:sol,qty,unit:p==='Virkon S'||p==='Peraclean 15'||p==='Oxteril 350 Combi'?'kg':'L'});alert('تمت إضافة التطبيق للتقرير. يمكنك الانتقال للمرحلة التالية.')}
function addSpecial(key){alert('هذه الخطوة تحتاج اختيار منتج وجرعة معتمدة. لن يتم احتسابها تلقائيًا قبل استكمال البيانات الفنية.')}
function go(d){if(step===0&&d<0){$('wizard').classList.add('hide');$('epidemicStep').classList.remove('hide');guidedProgress(1);return}if(step===STAGES.length-1&&d>0){guidedProgress(3);nav('report');return}step+=d;renderStep();window.scrollTo({top:0,behavior:'smooth'})}
function packFor(product){return PACKS.filter(p=>p[0]===product).sort((a,b)=>b[1]-a[1])}
function optimize(product,needed){let packs=packFor(product),best=null;if(!packs.length)return null;if(packs.length===1){let n=Math.ceil(needed/packs[0][1]);return {packs:[n],total:n*packs[0][1],cost:n*packs[0][3]}}let [a,b]=packs;for(let i=0;i<=Math.ceil(needed/a[1])+1;i++){let j=Math.max(0,Math.ceil((needed-i*a[1]-1e-9)/b[1])),total=i*a[1]+j*b[1],cost=i*a[3]+j*b[3];if(total+1e-8>=needed&&(!best||cost<best.cost||(cost===best.cost&&total<best.total)))best={packs:[i,j],total,cost}}return best}
function renderReport(){let sums={};let consumption=0;let totalSol=0;$('reportFarm').textContent=`المزرعة: ${$('farm').value||'—'} | العميل: ${$('customer').value||'—'} | المحافظة: ${$('gov').value} | عدد العنابر: ${num('houses')} | الطيور: ${fmt(num('birds'))} | مستوى الوبائية: ${$('risk').textContent}`;$('reportRows').innerHTML=records.map(r=>{let p=packFor(r.product),rate=p.length?p[0][3]/p[0][1]:0,cost=r.qty*rate;consumption+=cost;totalSol+=r.solution;if(!sums[r.product])sums[r.product]={qty:0,unit:r.unit};sums[r.product].qty+=r.qty;return `<tr><td>${r.stage}</td><td>${r.product}</td><td>${fmt(r.solution)}</td><td>${fmt(r.qty)} ${r.unit==='kg'?'كجم':'لتر'}</td><td>${money(cost)}</td></tr>`}).join('')||'<tr><td colspan="5">لم تتم إضافة تطبيقات بعد</td></tr>';let purchase=0;$('purchaseRows').innerHTML=Object.entries(sums).map(([name,s])=>{let p=packFor(name),opt=optimize(name,s.qty);if(!opt)return '';purchase+=opt.cost;let packs=opt.packs.map((n,i)=>n?`${n} × ${fmt(p[i][1])} ${p[i][2]==='kg'?'كجم':'لتر'}`:'').filter(Boolean).join(' + ');return `<tr><td>${name}</td><td>${fmt(s.qty)} ${s.unit==='kg'?'كجم':'لتر'}</td><td>${packs}</td><td>${fmt(opt.total)} ${s.unit==='kg'?'كجم':'لتر'}</td><td>${money(opt.cost)}</td></tr>`}).join('')||'<tr><td colspan="5">لا توجد عبوات مطلوبة</td></tr>';$('summary').innerHTML=`<div class="grid"><div class="stat">إجمالي المحاليل المخففة<b>${fmt(totalSol)} لتر</b></div><div class="stat">تكلفة الاستهلاك الفعلي<b>${money(consumption)} ج</b></div><div class="stat">تكلفة شراء العبوات<b>${money(purchase)} ج</b></div></div>`;let birds=num('birds'),houses=num('houses');$('totals').innerHTML=`<div class="grid2" style="margin-top:15px"><div class="stat">تكلفة الاستهلاك / عنبر<b>${money(houses?consumption/houses:0)} ج</b></div><div class="stat">تكلفة الاستهلاك / طائر<b>${money(birds?consumption/birds:0)} ج</b></div></div>`}
function buildCatalog(){let unique=[...new Set(PACKS.map(p=>p[0]))];$('catalogTiles').innerHTML=unique.map(name=>{let p=packFor(name),im=IMG[p[0][4]]||'',sizes=p.map(x=>`${fmt(x[1])} ${x[2]==='kg'?'كجم':'لتر'}`).join(' / ');return `<div class="tile">${im?`<img src="${im}" alt="${name}">`:'<div style="height:100px;background:#edf5fa;border-radius:9px"></div>'}<b>${name}</b><small>العبوات: ${sizes}</small></div>`}).join('')};buildCatalog();

const INNOVAL_API='https://opmbaaljwdqarnrgruax.supabase.co';
const INNOVAL_KEY='sb_publishable_xqT_ZjYGsJ_3i3VVSvDs8w_MLP9gPSl';
const PUBLIC_ASSETS=INNOVAL_API+'/storage/v1/object/public/product-assets/';
function assetUrl(path){return PUBLIC_ASSETS+String(path).split('/').map(encodeURIComponent).join('/')}
function safeText(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function buildCatalog(){
 const el=$('catalogTiles');el.innerHTML='<p class="muted">جاري تحميل المنتجات المنشورة من Supabase…</p>';
 try{
 const response=await fetch(INNOVAL_API+'/rest/v1/products?select=slug,name_ar,name_en,description_ar,description_en,pack_size,image_path&published=eq.true&order=name_en.asc',{headers:{'apikey':INNOVAL_KEY}});
 if(!response.ok)throw new Error('HTTP '+response.status);
 const products=await response.json();
 el.innerHTML=products.map(p=>`<article class="tile live-tile">${p.image_path?`<img loading="lazy" src="${assetUrl(p.image_path)}" alt="${safeText(p.name_ar||p.name_en)}" onerror="this.style.display='none';this.nextElementSibling.style.display='block'"><div style="display:none" class="muted">الصورة غير متاحة</div>`:'<div class="muted">الصورة غير متاحة</div>'}<b>${safeText(p.name_ar||p.name_en||p.slug)}</b><small>${safeText(p.name_en||'')}</small><small>العبوة: ${safeText(p.pack_size||'راجع بيانات العبوة')}</small>${p.description_ar?`<p class="muted">${safeText(p.description_ar)}</p>`:''}</article>`).join('')||'<p>لا توجد منتجات منشورة حاليًا.</p>';
 }catch(err){el.innerHTML='<p class="notice">تعذر تحميل المكتبة المباشرة. تأكد من اتصال الإنترنت وصلاحية قراءة المنتجات المنشورة، ثم حاول مجددًا.</p><button onclick="buildCatalog()">إعادة المحاولة</button>';console.warn('Catalog unavailable',err)}
}
function goHome(){$('home').classList.remove('hide');$('workArea').classList.add('hide');$('extraPage').classList.add('hide');window.scrollTo({top:0,behavior:'smooth'})}
function openService(which){
 if(which==='during'){alert('برنامج أثناء الدورة قيد الإعداد والمراجعة الفنية؛ لن نعرض جرعات غير معتمدة.');return}
 $('home').classList.add('hide');$('workArea').classList.remove('hide');
 if(which==='catalog'){nav('catalog');buildCatalog()}
 else{nav('planner');$('setup').classList.remove('hide');$('epidemicStep').classList.add('hide');$('wizard').classList.add('hide');guidedProgress(0);}
}
function enterGuest(){user={name:'زائر',gov:'المنوفية'};$('auth').classList.add('hide');$('app').classList.remove('hide');$('logout').style.display='none';$('who').textContent='وضع الزائر';goHome()}
enterGuest();

// V11: guest-only farm workspace, independent of public Supabase catalog.
const FARM_STORE='innoval.biosecurity.farms.v11';
const REPORT_STORE='innoval.biosecurity.reports.v11';
const PROFILE_STORE='innoval.biosecurity.profile.v11';
const localRead=(k)=>{try{return JSON.parse(localStorage.getItem(k)||'[]')}catch{return []}};
const localWrite=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch(e){alert('تعذر الحفظ على هذا الجهاز. تحقق من إعدادات التخزين.');return false}};
let selectedFarmId=null;
const fieldIds=['farm','customer','phone','gov','birdType','housing','len','wid','hei','houses','birds','mort','batL','batW','batH','batRows','diseaseHistory','cocciHistory'];
function farmValues(){let v={};fieldIds.forEach(k=>{let e=document.getElementById(k);if(e)v[k]=e.value});return v}
function loadFarm(id){const x=localRead(FARM_STORE).find(f=>f.id===id);if(!x)return;selectedFarmId=id;Object.entries(x.data).forEach(([k,v])=>{const e=document.getElementById(k);if(e)e.value=v});toggleBattery();riskUpdate();openService('between')}
function saveFarmFromForm(){let data=farmValues();if(!data.farm.trim()){alert('اكتب اسم المزرعة الأول');return null}if(!(Number(data.len)>0&&Number(data.wid)>0&&Number(data.hei)>0&&Number(data.houses)>0&&Number(data.birds)>0)){alert('أدخل أبعاد العنبر وعدد العنابر والطيور بشكل صحيح');return null}if(Number(data.mort)<0||Number(data.mort)>100||data.mort===''){alert('نسبة النفوق يجب أن تكون بين 0 و100%');return null}if(data.housing==='battery'&&!(Number(data.batL)>0&&Number(data.batW)>0&&Number(data.batH)>0&&Number(data.batRows)>0)){alert('أدخل أبعاد البطاريات وعدد الصفوف');return null}let all=localRead(FARM_STORE);let id=selectedFarmId||('farm-'+Date.now());let old=all.find(f=>f.id===id);let obj={id,data,updated:new Date().toISOString(),created:old?.created||new Date().toISOString()};all=all.filter(f=>f.id!==id);all.unshift(obj);if(localWrite(FARM_STORE,all)){selectedFarmId=id;return id}return null}
function guidedProgress(n){const titles=['خلّينا نتعرف على مزرعتك','نراجع الحالة الوبائية','برنامجك خطوة بخطوة','تقرير مزرعتك'];const el=document.getElementById('journeyTitle');if(el)el.textContent=titles[n]||titles[0];const bar=document.getElementById('journeyProgress');if(bar)bar.querySelectorAll('i').forEach((x,i)=>x.classList.toggle('filled',i<=n));}
function guidedNext(){if(!$('farm').value.trim()){alert('اكتب اسم المزرعة علشان تحفظ برنامجك باسمها');$('farm').focus();return}for(const id of ['len','wid','hei','houses','birds']){if(!(Number($(id).value)>0)){alert('راجع أبعاد العنبر وعدد العنابر والطيور');$(id).focus();return}}if($('housing').value==='battery'&&['batL','batW','batH','batRows'].some(id=>!(Number($(id).value)>0))){alert('راجع بيانات البطاريات');return}$('setup').classList.add('hide');$('epidemicStep').classList.remove('hide');guidedProgress(1);window.scrollTo({top:0,behavior:'smooth'});}
function guidedBack(){if(!$('wizard').classList.contains('hide')){$('wizard').classList.add('hide');$('epidemicStep').classList.remove('hide');guidedProgress(1)}else if(!$('epidemicStep').classList.contains('hide')){$('epidemicStep').classList.add('hide');$('setup').classList.remove('hide');guidedProgress(0)}else{goHome()}window.scrollTo({top:0,behavior:'smooth'});}
function startGuided(){if(!saveFarmFromForm())return;const disease=document.getElementById('diseaseHistory').value;if(disease!=='no'){if(!confirm('تم تسجيل تاريخ مرضي أو اشتباه. البرنامج إرشادي ويحتاج مراجعة الطبيب البيطري المسؤول قبل اختيار المطهرات. هل تريد المتابعة؟'))return}records.length=0;$('epidemicStep').classList.add('hide');guidedProgress(2);start()}
function saveCurrentReport(){if(!selectedFarmId){if(!saveFarmFromForm())return}renderReport();const all=localRead(REPORT_STORE);const farm=localRead(FARM_STORE).find(f=>f.id===selectedFarmId);const report={id:'report-'+Date.now(),farmId:selectedFarmId,farmName:farm?.data.farm||'مزرعة',created:new Date().toISOString(),records:JSON.parse(JSON.stringify(records)),inputs:farmValues(),html:{farm:document.getElementById('reportFarm').textContent,summary:document.getElementById('summary').innerHTML,rows:document.getElementById('reportRows').innerHTML,purchase:document.getElementById('purchaseRows').innerHTML,totals:document.getElementById('totals').innerHTML}};all.unshift(report);if(localWrite(REPORT_STORE,all))alert('تم حفظ التقرير محليًا. تقدر تراجعه من تقاريري.')}
function showSavedReport(id){const r=localRead(REPORT_STORE).find(x=>x.id===id);if(!r)return;showPage('reports');document.getElementById('extraBody').innerHTML='<h2>📊 تقرير '+safeText(r.farmName)+'</h2><p class="muted">'+new Date(r.created).toLocaleString('ar-EG')+'</p><p>'+safeText(r.html.farm)+'</p>'+r.html.summary+'<h3>تفاصيل الاستهلاك</h3><div class="tablewrap"><table><thead><tr><th>المرحلة</th><th>المنتج</th><th>المحلول</th><th>المركز</th><th>التكلفة</th></tr></thead><tbody>'+r.html.rows+'</tbody></table></div><h3>العبوات</h3><div class="tablewrap"><table><thead><tr><th>المنتج</th><th>المطلوب</th><th>العبوات</th><th>المشتراة</th><th>التكلفة</th></tr></thead><tbody>'+r.html.purchase+'</tbody></table></div>'+r.html.totals+'<p class="muted">هذا تقرير محفوظ محليًا؛ يجب التحقق من الجرعات وتعليمات المنتج قبل التطبيق.</p>'}
function deleteFarm(id){if(!confirm('حذف المزرعة من هذا الجهاز؟ التقارير المحفوظة ستظل موجودة.'))return;localWrite(FARM_STORE,localRead(FARM_STORE).filter(x=>x.id!==id));if(selectedFarmId===id)selectedFarmId=null;showPage('farms')}
function showPage(page){document.getElementById('home').classList.add('hide');document.getElementById('workArea').classList.add('hide');document.getElementById('extraPage').classList.remove('hide');const el=document.getElementById('extraBody');const farms=localRead(FARM_STORE),reports=localRead(REPORT_STORE);if(page==='farms'){el.innerHTML='<h2>🏡 مزارعي</h2><p class="muted">كل مزرعة مستقلة باسمها وأبعادها وبياناتها. البيانات محفوظة على هذا المتصفح فقط.</p><div class="actions"><button onclick="newFarm()">+ إضافة مزرعة</button></div>'+(farms.length?farms.map(f=>'<div class="mini-card"><b>'+safeText(f.data.farm)+'</b><p class="muted">'+safeText(f.data.birdType)+' • '+safeText(f.data.housing==='battery'?'بطاريات':'أرضي')+' • '+safeText(f.data.houses)+' عنبر • '+safeText(f.data.len)+' × '+safeText(f.data.wid)+' متر</p><div class="actions"><button onclick="loadFarm(\''+f.id+'\')">فتح / تعديل</button><button class="alt" onclick="deleteFarm(\''+f.id+'\')">حذف</button></div></div>').join(''):'<div class="empty-state">لسه مفيش مزارع محفوظة. أضف أول مزرعة علشان نبدأ.</div>')}
else if(page==='reports'){el.innerHTML='<h2>📊 تقاريري</h2><p class="muted">التقارير بتتحفظ لما تضغط «حفظ التقرير» في نهاية البرنامج.</p>'+(reports.length?reports.map(r=>'<div class="mini-card"><b>'+safeText(r.farmName)+'</b><p class="muted">'+new Date(r.created).toLocaleString('ar-EG')+' • '+r.records.length+' تطبيقات محسوبة</p><button onclick="showSavedReport(\''+r.id+'\')">عرض التقرير</button></div>').join(''):'<div class="empty-state">مافيش تقارير محفوظة لسه.</div>')}
else if(page==='profile'){const prof=localRead(PROFILE_STORE);el.innerHTML='<h2>👤 البروفايل</h2><p class="muted">اختياري، من غير حساب أو رفع بيانات للسيرفر.</p><label>اسم المستخدم</label><input id="profileName" value="'+safeText(prof.name||'')+'" placeholder="اسمك"><div class="actions"><button onclick="localWrite(PROFILE_STORE,{name:document.getElementById(\'profileName\').value});alert(\'تم الحفظ على الجهاز\')">حفظ</button></div><div class="notice" style="margin-top:16px">وضع الزائر: المزارع والتقارير لا تنتقل تلقائيًا بين الأجهزة. مسح بيانات المتصفح قد يؤدي لفقدانها.</div>'}
else if(page==='notifications'){el.innerHTML='<h2>🔔 الإشعارات</h2><div class="mini-card"><b>أهلاً بيك في Innoval Biosecurity</b><p class="muted">تقدر تضيف مزارع متعددة وتصمم برنامج مستقل لكل مزرعة.</p></div><p class="muted">الإشعارات الفعلية Push Notifications لسه غير مفعلة في النسخة التجريبية.</p>';document.getElementById('noticeCount').style.display='none'}
window.scrollTo({top:0,behavior:'smooth'})}
function newFarm(){selectedFarmId=null;document.getElementById('farm').value='';document.getElementById('customer').value='';document.getElementById('phone').value='';document.getElementById('mort').value='';document.getElementById('diseaseHistory').value='no';document.getElementById('cocciHistory').value='no';openService('between')}
const _goHome=goHome;goHome=function(){document.getElementById('extraPage').classList.add('hide');_goHome()};
const _openService=openService;openService=function(which){document.getElementById('extraPage').classList.add('hide');_openService(which)};

initPilotAuth();
